"""Complete frozen secondary diagnostics and publish an evidence-based report."""
from pathlib import Path
import json
import numpy as np
import polars as pl
from run_tokyo_fix_program3_ohlcv_execution_20261011_v1 import ROOT,SID,OUT,estimate,controls,save,sha


def main():
    complete=json.loads((OUT/'analysis_corrected.json').read_text())
    proxy=json.loads((OUT/'T1_proxy/result.json').read_text())
    events=pl.read_parquet(OUT/'proxy_event_panel.parquet')
    categories=[];means=[]
    for item in proxy['categories']:
        feature=item['feature'];end=item['horizon'];lo,hi=item['development_cuts']
        gate='proxy0830_complete' if feature=='extension0830' else 'proxy0930_complete'
        d=events.filter(pl.col(gate)).drop_nulls([feature,f'y{end}']).sort('session')
        low=(d[feature]<=lo).cast(pl.Float64).to_numpy();high=(d[feature]>hi).cast(pl.Float64).to_numpy();g=d['gotobi'].cast(pl.Float64).to_numpy()
        # Middle ordinary is baseline; low/high and Gotobi interactions are secondary.
        x=np.column_stack([*controls(d),g,low,high,g*low,g*high]);y=d[f'y{end}'].to_numpy();idx=len(controls(d))
        categories.append({'feature':feature,'horizon':end,'n':d.height,'baseline':'middle ordinary','effects':{name:estimate(y,x,idx+i,np.array([str(s)[:7] for s in d['session']])) for i,name in enumerate(['gotobi_middle','low','high','gotobi_low_increment','gotobi_high_increment'])},'inferential_status':'Secondary descriptive estimates; no corrected-significance claim, no strategy filter'})
    for r in complete['results']:
        d=pl.read_parquet(OUT/'runs_corrected'/r['id']/'signals.parquet').sort('session')
        for s in r['scenarios']:
            vals=d[f'net_usd_c{s["cost_pips"]}'].fill_null(0).to_numpy()
            filled=d.filter(pl.col('filled'))[f'net_usd_c{s["cost_pips"]}'].to_numpy()
            means.append({'id':r['id'],'cost':s['cost_pips'],'per_signal_hac':estimate(vals,np.ones((len(vals),1))), 'per_fill_hac':estimate(filled,np.ones((len(filled),1))), 'classification':'Cost overlays and confidence bounds descriptive; no selected winner'})
    save(OUT/'secondary_diagnostics.json',{'categorical_controlled_HAC':categories,'expectancy_intervals':means,'no_new_strategy_trials':True})
    tab=[]
    for r in complete['results']:
        for s in r['scenarios']:
            tab.append({'id':r['id'],'offset':r['variant'].get('offset'),'ttl':r['variant'].get('ttl'),'buffer':r['variant'].get('buffer'),'submitted':r['submitted'],'touched':r['touched'],'filled':r['filled'],'missed_cancelled':r['missed'],**{k:v for k,v in s.items() if k not in ['years','mtm_caveat']}})
    pl.DataFrame(tab).write_csv(OUT/'all_cost_fill_metrics.csv')
    report=ROOT/f'docs/audit/{SID}.md'
    rows=complete['results']; market=rows[0]
    summary=lambda r:next(s for s in r['scenarios'] if s['cost_pips']==1)
    comp=json.loads((OUT/'T2_comparison_corrected/result.json').read_text())
    lines=[f'# Tokyo Fix Program3: OHLCV execution audit', '', '**Decision: RESEARCH COMPLETE / EXPLORATORY / NOT_APPROVED.**', '', 'The post-fix Gotobi short does not remain robustly positive under the frozen conservative limit-fill bounds. At the assumed 1-pip roundtrip cost, the native market benchmark earns $212.27 on 468 signals. Eleven of twelve native limit bounds lose money. The +1-pip offset, 3-minute TTL, zero-buffer bound earns $18.99, or $0.041 per submitted signal. Its 0.5-pip-buffer version loses $64.59. Every limit bound loses money in Jan–Aug2026. This rejects the stated robustness criterion. No winner was selected.', '', '## Evidence scope and source seal', '', '**VERIFIED:** Seven immutable annual LSE USDJPY minute OHLCV snapshots and the inherited Tokyo bank calendar supply 2020 through August2026. UTC timestamps denote minute opens and are converted to Asia/Tokyo. No data at or after2026-09-01 JST were read. All sources have SHA256 identities in `source_manifest.json`. Earlier Program1/2 artifacts and unrelated dirty files remain preserved.', '', '**INFERENCE:** A minute close becomes available one minute after its open timestamp. The simulation uses09:54 close as the reference available at09:55. It never uses09:55 close to submit the order. The first permitted fill is09:56.', '', '**UNKNOWN:** Prices are vendor composites. Volume is not verified executed FX volume. The local inventory has no USDJPY tick, paired bid/ask or depth data. Legacy8,507 BID candle files are not executable quotes. Broker contract, commissions, spread, lot constraints, queue position, latency, actual passive-fill probability, capacity and dealer inventory remain unknown. The notional is fixed USD10,000, with USD10,000 initial equity and no compounding. This is a research price proxy for an unspecified retail FX contract.', '', 'All studied years were already observed. 2020–23 is development, 2024–25 is retrospective validation, and Jan–Aug2026 is observed regime stress. September–October2026 remains sealed. No period is relabeled unseen OOS.', '', '## Completeness and execution contract', '', f'**VERIFIED:** The09:54–10:30 contiguous minute gate retains {complete["cohort_n"]} bank dates: {complete["gotobi_n"]} Gotobi and {complete["ordinary_n"]} ordinary. The gate requires each timestamp and valid finite OHLC geometry. `window_gates.parquet` and `T0_quality/result.json` retain missingness by year, weekday and Gotobi. Proxy and placebo windows use their own completeness gates. No fill is forward-filled. Five-minute staleness and zero volume are reported; unchanged composite closes alone do not establish an unavailable quote.', '', 'Native `ml4t.backtest.Engine`0.1.7 matches LIMIT orders on inclusive touches. Native fixed slippage can violate the sell limit price. The supported `PositiveVolumeLimit` execution gate therefore receives synthetic0/1 eligibility volume; raw OHLC remains unchanged. The gate permits a sell fill only when high strictly exceeds limit plus buffer within the frozen TTL. This gate is a hypothetical execution bound, not signal information or measured fill probability. The native engine owns fills, positions, cancellation and account cash. No second backtest loop exists.', '', 'The sell limit equals09:54 close plus0/0.5/1pip. Native price is the exact limit; favorable gap improvement is not assumed. TTL1 allows09:56; TTL3 allows09:56–09:58. Cancellation occurs after the last permitted matching cycle. Filled shorts close through a native MARKET submission at10:09 and fill at10:10 open. Missed signals have no invented trade and no closing order. There is no overnight or post-exit exposure.', '', 'The native ledger is JPY. Each closed JPY profit is divided by its actual raw exit USDJPY price. Assumed all-in costs0.8/1.0/1.4/2.0pips are separate quote-currency cash-flow overlays, not changes to native limit prices. Market and passive scenarios have separate illustrative entry/exit budgets but equal total costs. There is no maker rebate or zero-spread assumption. Actual costs are unverified.', '', '## Native results at1-pip roundtrip cost', '', '| Arm | Signals | Touches | Fills | Missed/cancelled | Net USD | USD/signal | USD/fill | Win rate | PF | Daily Sharpe | Close DD% | Minute-close MTM DD% |', '|---|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|']
    for r in rows:
        s=summary(r)
        lines.append(f'| {r["id"]} | {r["submitted"]} | {r["touched"]} | {r["filled"]} | {r["missed"]} | {s["net_usd"]:.2f} | {s["per_signal_usd"]:.3f} | {s["per_fill_usd"]:.3f} | {s["win_rate"]:.1%} | {s["profit_factor"]:.3f} | {s["daily_sharpe"]:.3f} | {s["max_closed_drawdown_pct"]:.3f} | {s["minute_close_mtm_drawdown_pct"]:.3f} |')
    lines += ['', 'All missed limit orders terminate through cancellation; native expired count is0. Sharpe uses daily USD portfolio equity changes on the full Tokyo bank calendar, including flat days, with252 periods/year. `EquityCurve` and `TradeAnalyzer` calculate performance metrics. Closed-trade drawdown differs from the native-fill-based minute-close MTM reconstruction. MTM reserves the full assumed cost on entry and excludes unobserved tick/intrabar extrema and actual broker margin.', '', '| Arm | Net USD at0.8pip | 1.0pip | 1.4pip | 2.0pip |', '|---|---:|---:|---:|---:|']
    for r in rows:lines.append('| '+r['id']+' | '+' | '.join(f'{s["net_usd"]:.2f}' for s in r['scenarios'])+' |')
    lines += ['', 'Full annual metrics, per-fill/per-signal expectations, negative-day counts, win rates, Sharpe, profit factor, and drawdown for all56 cost scenarios are in `all_cost_fill_metrics.csv` and each corrected run result. The following table shows selected reference arms; it does not select a strategy.', '', '| Year | Market Gotobi USD | Ordinary USD | +1pip/TTL3/buffer0 USD | +1pip/TTL3/buffer0.5 USD |', '|---|---:|---:|---:|---:|']
    named={r['id']:r for r in rows}
    for i,y in enumerate(range(2020,2027)):lines.append(f'| {y}{" Jan–Aug" if y==2026 else ""} | '+' | '.join(f'{summary(named[n])["years"][i]["net_usd"]:.2f}' for n in ['market_gotobi','market_ordinary','limit_o1_t3_b0','limit_o1_t3_b0p5'])+' |')
    lines += ['', '## Price proxies, controls and adverse selection', '', '**HYPOTHESIS:** Settlement demand and subsequent inventory unwind can explain a reversal, but price extensions, realized volatility, acceleration and range do not observe that mechanism. The five past-only proxies use completed bars. Development-only terciles stay fixed. Event-level correlation, native `Evaluator` annual expanding folds, categorical controls and HAC/month-cluster intervals are saved. `analyze_signal` requires cross-sectional prices; the single-asset event study instead uses the library event correlation and `Evaluator` APIs.', '', '**VERIFIED:** None of the20 weekday/year-controlled proxy contrasts passes Holm. Secondary categorical/interaction estimates are descriptive. `secondary_diagnostics.json` contains controlled categorical HAC estimates and per-signal/per-fill cost expectancy intervals. No price proxy filters trades.', '', 'The market Gotobi-minus-ordinary increment is1.420pips, HAC95%CI[0.397,2.442], raw p0.00652 and Holm14 p0.0652. The matched09:26–09:40 nonfix placebo contrast has466 Gotobi pairs: fix-minus-placebo short return2.704pips, CI[1.625,3.782], Holm14 p0.0000164. This single frozen placebo result is retrospective and cannot prove settlement causality or correct prior searches.', '', 'All twelve limit policies have lower per-signal expectation than the market policy. Three differences pass the new14-contrast Holm correction. Raw1/3-minute and exit markouts, market outcomes conditional on filled/missed days, and matched policy contrasts are in `T2_comparison_corrected/result.json`. These records expose missed favorable market trades and adverse excursions. The fill bound uses crossing and time only, never the subsequent exit outcome.', '', 'Earlier native Program1v2 used458 Gotobi/1,143ordinary trades and a broader08:29–10:10 gate. Its after-cost results were+$217.14/−$450.95. Those frozen artifacts remain intact. The new cohort and raw-exit cost-overlay conversion differ, so this is not an exact same-cohort reproduction.', '', '## Independent audit and retained failures', '', '**VERIFIED:** `T3_oracle/result.json` independently rescans original snapshots and checks every submitted signal, earliest strict crossing, exact limit price, TTL, no same-bar fill, missed cancellation, scheduled exit, quote-PnL reconciliation and USD conversion. The oracle uses decimal arithmetic independently of the production Polars gate.', '', 'The first full14-run implementation admitted some exact decimal touches because of binary floating-point arithmetic. Independent verification rejected six limit runs. All initial run artifacts, initial comparison and ledger entries remain in `runs/`, `analysis_complete.json` and `T2_comparison/`; they are superseded as evidence. The corrected full14-run replay is under `runs_corrected/`, `analysis_corrected.json` and `T2_comparison_corrected/`. Comparison rounds to8decimal places solely to remove observed floating dust below3e-14JPY; source prices are unchanged. This is a strict-cross implementation repair, not a new parameter ladder.', '', 'Execution accounting includes28 complete native runs, including14 corrective replays. Three earlier runtime failures were retained: UTC/JST literal mismatch, required feature volume omitted, and touch-count join missing the session key. Logs, code identities, correction dispositions and every initial/corrected result hash are in `execution_accounting.json`. The immutable CLI terminal records show that the original trials executed; completion alone did not validate their fills. Final audit points to corrected evidence and preserves rejected originals.', '', 'Focused regression tests and native semantics probes are reported in `T4_final_audit/result.json`. The full304-item repository suite was attempted and interrupted after it stalled near47%; a full-suite pass is not claimed. The first `uv` attempt could not write its user cache; the retry used a task-specific writable cache and the installed environment. No notebook was changed.', '', '## Limits and next decisive input', '', '**INFERENCE:** Conservative crossing and missed-fill sensitivity erode the apparent historical market edge. The model does not establish an executable passive strategy. The frozen robustness falsifier fails, and deployment remains NOT_APPROVED.', '', '**UNKNOWN:** Real order-book queues and adverse broker selection cannot be estimated from these bars. Obtain timestamp-verified executable bid/ask and actual passive order outcomes on genuinely future data, then preregister another test. Do not open the sealed holdout for optimization. Prior historical trial history is incomplete; DSR/PBO and any full-search confidence adjustment remain unreproducible.', '', '## Artifacts and reproduction', '', f'- Frozen spec: `config/research_sessions/{SID}.yaml`.', f'- Runner: `scripts/run_{SID}.py`; modes `prepare`, `run`, `run_corrected`. Existing immutable outputs block changes; resumption verifies identical data.', f'- Independent oracle: `scripts/verify_{SID}.py`.', f'- Supplement/report: `scripts/supplement_{SID}.py`.', '- Authoritative executions: `runs_corrected/*/orders.parquet`, `trades.parquet`, `signals.parquet`, `result.json`.', '- Charts: [price proxy map](../../run_log/'+SID+'/price_proxy_map.png), [corrected cost/fill sensitivity](../../run_log/'+SID+'/fill_cost_sensitivity_corrected.png).', '- Source/window evidence: `source_manifest.json`, `window_gates.parquet`, `T0_quality/result.json`.', '- Independent audit: `T3_oracle/result.json`; final preservation/ledger/verification: `T4_final_audit/result.json`.', '', 'No real orders, commits, pushes, old frozen artifact changes or holdout analysis occurred.']
    with report.open('x') as f:f.write('\n'.join(lines)+'\n')
    print(report)

if __name__=='__main__':main()
